<?php
declare(strict_types=1);require __DIR__.'/includes/bootstrap.php';require __DIR__.'/includes/auth.php';require __DIR__.'/includes/project_manager.php';require_permission('project_time.view');$pdo=db();$projectId=(int)($_GET['project_id']??0);$userId=(int)($_GET['user_id']??0);$from=preg_match('/^\d{4}-\d{2}-\d{2}$/',(string)($_GET['from']??''))?$_GET['from']:date('Y-m-01');$to=preg_match('/^\d{4}-\d{2}-\d{2}$/',(string)($_GET['to']??''))?$_GET['to']:date('Y-m-t');$project=$projectId?pm_fetch_project($pdo,$projectId):null;$projects=pm_project_options($pdo);$users=$pdo->query('SELECT id,name FROM users WHERE is_active=1 ORDER BY name')->fetchAll();$where=['te.work_date BETWEEN ? AND ?'];$params=[$from,$to];if($projectId){$where[]='te.project_id=?';$params[]=$projectId;}if($userId){$where[]='te.user_id=?';$params[]=$userId;}$s=$pdo->prepare("SELECT te.*,p.name project_name,t.title task_title,u.name user_name FROM project_time_entries te JOIN projects p ON p.id=te.project_id JOIN users u ON u.id=te.user_id LEFT JOIN project_tasks t ON t.id=te.task_id WHERE ".implode(' AND ',$where)." ORDER BY te.work_date DESC,te.id DESC");$s->execute($params);$rows=$s->fetchAll();$total=array_sum(array_map(fn($r)=>(float)$r['hours'],$rows));$billable=array_sum(array_map(fn($r)=>$r['billable']?(float)$r['hours']:0,$rows));$nonBillable=max(0,$total-$billable);$value=array_sum(array_map(fn($r)=>$r['billable']?(float)$r['hours']*(float)$r['hourly_rate']:0,$rows));$activeDays=count(array_unique(array_column($rows,'work_date')));$avg=$activeDays?$total/$activeDays:0;$userLoads=[];foreach($rows as$r){$userLoads[$r['user_name']]=($userLoads[$r['user_name']]??0)+(float)$r['hours'];}arsort($userLoads);$maxLoad=max(1,...array_values($userLoads?:[1]));$billPct=$total?(int)round($billable/$total*100):0;$pageTitle='Horas y recursos';require __DIR__.'/includes/header.php';if($project)echo pm_project_tabs($projectId,'time');?>
<div class="project-hero compact"><div><span class="eyebrow">TIEMPO & RECURSOS</span><h2>Horas y carga de trabajo</h2><p>Quién trabajó, en qué proyecto, cuánto tiempo invirtió y cuánto de ese esfuerzo es facturable.</p></div><?php if(has_permission('project_time.manage')):?><a class="btn btn-primary" href="project_time_form.php<?=$projectId?'?project_id='.$projectId:''?>">+ REGISTRAR HORAS</a><?php endif;?></div>
<div class="timesheet-summary"><div class="timesheet-kpi"><small>Horas registradas</small><strong><?=e(number_format($total,1,',','.'))?> h</strong><span><?=e(pm_date($from))?> → <?=e(pm_date($to))?></span></div><div class="timesheet-kpi"><small>Horas facturables</small><strong><?=e(number_format($billable,1,',','.'))?> h</strong><span><?=$billPct?>% del tiempo</span></div><div class="timesheet-kpi"><small>No facturables</small><strong><?=e(number_format($nonBillable,1,',','.'))?> h</strong><span>Trabajo interno / incluido</span></div><div class="timesheet-kpi"><small>Valor estimado</small><strong><?=e(number_format($value,2,',','.'))?></strong><span>Horas facturables × tarifa</span></div><div class="timesheet-kpi"><small>Promedio por día</small><strong><?=e(number_format($avg,1,',','.'))?> h</strong><span><?=$activeDays?> día(s) con registros</span></div></div>
<div class="workload-grid"><section class="workload-card"><h3>Carga por persona</h3><?php if(!$userLoads):?><div class="empty">Aún no hay horas en este período.</div><?php else:?><?php foreach(array_slice($userLoads,0,8,true) as$name=>$hours):?><div class="person-load"><div><strong><?=e($name)?></strong><small><?=e(number_format($hours,1,',','.'))?> h</small></div><div class="load-track"><i style="width:<?=max(5,round($hours/$maxLoad*100))?>%"></i></div><b><?=e(number_format($hours/$total*100,0))?>%</b></div><?php endforeach;?><?php endif;?></section><section class="workload-card"><h3>Tiempo facturable</h3><div class="billable-ring" style="--pct:<?=$billPct?>"><strong><?=$billPct?>%</strong></div><p class="muted" style="text-align:center">De <?=e(number_format($total,1,',','.'))?> horas, <?=e(number_format($billable,1,',','.'))?> pueden imputarse al cliente.</p><div class="details-grid" style="grid-template-columns:1fr 1fr"><div class="detail"><small>Facturable</small><strong><?=e(number_format($billable,1,',','.'))?> h</strong></div><div class="detail"><small>Interno</small><strong><?=e(number_format($nonBillable,1,',','.'))?> h</strong></div></div></section></div>
<section class="panel"><div class="panel-header"><div><h2>Detalle del período</h2><span class="table-sub">Cada fila explica persona, proyecto, tarea, trabajo y horas.</span></div></div><div class="panel-body"><form method="get" class="filters-wide"><label>Proyecto<select name="project_id"><option value="0">Todos los proyectos</option><?php foreach($projects as$p):?><option value="<?=$p['id']?>" <?=$projectId===(int)$p['id']?'selected':''?>><?=e($p['name'])?></option><?php endforeach;?></select></label><label>Persona<select name="user_id"><option value="0">Todo el equipo</option><?php foreach($users as$u):?><option value="<?=$u['id']?>" <?=$userId===(int)$u['id']?'selected':''?>><?=e($u['name'])?></option><?php endforeach;?></select></label><label>Desde<input type="date" name="from" value="<?=e($from)?>"></label><label>Hasta<input type="date" name="to" value="<?=e($to)?>"></label><button class="btn btn-secondary">APLICAR FILTROS</button></form></div><div class="table-wrap"><table class="data-table timesheet-table"><thead><tr><th>Fecha</th><th>Persona</th><th>Proyecto</th><th>Tarea</th><th>Trabajo realizado</th><th>Horas</th><th>Facturable</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="7" class="empty">Sin horas registradas.</td></tr><?php endif;?><?php foreach($rows as$r):?><tr><td><?=e(pm_date($r['work_date']))?></td><td><strong><?=e($r['user_name'])?></strong></td><td><a class="table-title" href="project_view.php?id=<?=(int)$r['project_id']?>"><?=e($r['project_name'])?></a></td><td><?=e($r['task_title']?:'Trabajo general')?></td><td><?=e($r['description']?:'Sin detalle adicional')?></td><td><span class="hours-pill"><?=e(number_format((float)$r['hours'],2,',','.'))?> h</span></td><td><?=$r['billable']?'<span class="badge badge-green">Sí · facturable</span>':'<span class="badge badge-gray">No · interno</span>'?></td></tr><?php endforeach;?></tbody></table></div></section><?php require __DIR__.'/includes/footer.php';?>
